    const s = turn?.startedAt ? Math.max(0, Math.floor((Date.now() - turn.startedAt) / 1000)) : 0;
    const secs = Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0');
    if (time.textContent !== secs) time.textContent = secs;
