    side = next;
    pill.hidden = !next;
    if (!next) { clearTimeout(tickTimer); tickTimer = 0; return; }
    pill.dataset.side = next;
    pill.style.top = next === 'top' ? (messages.offsetTop + 8) + 'px' : '';
